update public.hoeren_exercises set learning_aids = $j${"items":{"56":{"keyword":"nicht persönlich erreichbar + Nachricht = Anrufbeantworter","audio_end":41.1,"audio_start":35.3,"evidence_text":"Leider sind wir im Moment **nicht persönlich erreichbar**. Unser Laden ist heute wegen einer Inventur geschlossen.","explanation_wrong":"اختيار \"falsch\" خطأ لأن النص يطلب صراحةً ترك رسالة (Nachricht hinterlassen)، أي أنه جهاز الرد الآلي للمكتبة.","explanation_correct":"التسجيل رسالة آلية من مكتبة: \"nicht persönlich erreichbar\" ويُطلب ترك رسالة، وهذا هو جواب الهاتف الآلي، فالعبارة صحيحة.","evidence_translation":"للأسف لا يمكن الوصول إلينا شخصياً في الوقت الحالي. متجرنا مغلق اليوم بسبب الجرد."},"57":{"keyword":"ausschließlich eingeladene Künstler ↔ selbst Musik machen","audio_end":112.7,"audio_start":105.6,"evidence_text":"Bitte beachten Sie, die Musikvorführungen werden **ausschließlich von den eingeladenen Künstlern** gestaltet.","explanation_wrong":"اختيار \"richtig\" فخ: يوجد برنامج موسيقي، لكنه للفنانين المدعوين فقط، والزوار لا يستطيعون العزف.","explanation_correct":"النص يقول \"ausschließlich von den eingeladenen Künstlern\" ثم إن الآلات الخاصة ممنوعة، فلا يمكن للزوار العزف بأنفسهم؛ لذا العبارة خاطئة.","evidence_translation":"يرجى الانتباه: العروض الموسيقية يقدّمها حصراً الفنانون المدعوون."},"58":{"keyword":"keine Tanzveranstaltung ↔ gerne tanzen","audio_end":171.5,"audio_start":168.6,"evidence_text":"Dies ist **keine Tanzveranstaltung für Besucher**.","explanation_wrong":"اختيار \"richtig\" خطأ: الزوار يشاهدون فقط، ولا يرقصون، والرقص ممكن فقط في حفل سبتمبر.","explanation_correct":"الفعالية ليست للرقص: \"keine Tanzveranstaltung für Besucher\"، ومن يريد الرقص عليه انتظار أمسية الرقص في سبتمبر. والمكان هو Stadtplatz وليس Kulmbach.","evidence_translation":"هذه ليست فعالية رقص للزوار."},"59":{"keyword":"ausschließlich persönlich ↔ Online-Registrierung","audio_end":229.1,"audio_start":225.3,"evidence_text":"Eine **Online-Registrierung** über das Internet ist leider nicht möglich.","explanation_wrong":"اختيار \"richtig\" خطأ لأنه يعاكس النص؛ كلمة \"ausschließlich persönlich\" تستبعد أي تسجيل عبر الإنترنت.","explanation_correct":"النص ينفي صراحةً التسجيل عبر الإنترنت: \"nicht möglich\"، والتسجيل شخصياً فقط في المكتب، لذا العبارة خاطئة.","evidence_translation":"التسجيل عبر الإنترنت للأسف غير ممكن."},"60":{"keyword":"internationale Künstler ↔ verschiedene Plätze","audio_end":292.2,"audio_start":277.5,"evidence_text":"Alle Veranstaltungen finden **an verschiedenen Plätzen gleichzeitig** statt, sodass Sie frei entscheiden können, wo Sie zuschauen möchten.","explanation_wrong":"اختيار \"falsch\" خطأ: الفنانون دوليون فعلاً، والعروض في الساحة والمتنزهات وشارع المشاة، أي أماكن متعددة.","explanation_correct":"يقول النص إن فنانين من فرنسا وإسبانيا والبرازيل وغيرها يؤدون \"an verschiedenen Plätzen\" في إيسنس، فالعبارة صحيحة.","evidence_translation":"تقام جميع الفعاليات في أماكن مختلفة في الوقت نفسه، بحيث يمكنكم أن تقرروا بحرية أين تريدون المشاهدة."}},"translation":{"questions":{"56":"تسمعون رسالة البريد الصوتي لمكتبة.","57":"خلال حفل اليوبيل في القلعة يمكن للمرء العزف بنفسه.","58":"من يحب الرقص لفترة طويلة، عليه بزيارة كولمباخ.","59":"يمكنكم التسجيل لجميع الدورات أيضاً عبر الإنترنت.","60":"يقدم فنانون دوليون عروضاً في أماكن مختلفة في إيزنس."}}}$j$::jsonb where id = '3b392e61-14bd-46a3-9f76-649f99f0e22c';
update public.hoeren_transcripts set audio_path = 'notag/teil3/buchhandlung.m4a', duration_s = 305.7, text = $j$Hörverstehen Teil 3. Sie hören jetzt fünf kurze Texte. Dazu sollen Sie fünf Aufgaben lösen. Sie hören diese Ansage nur einmal. Entscheiden Sie beim Hören, ob die Aussagen 56, 60 richtig oder falsch sind. Nummer 56 Guten Tag und herzlich willkommen bei der Buchhandlung Lesezeit. Leider sind wir im Moment nicht persönlich erreichbar. Unser Laden ist heute wegen einer Inventur geschlossen. Sie können uns aber gerne eine Nachricht hinterlassen. Bitte nennen Sie dabei Ihren Namen, Ihre Telefonnummer und den Grund Ihres Anrufs. Falls Sie eine Bestellung aufgeben oder ein bereits bestelltes Buch abholen möchten, geben Sie bitte auch die Bestellnummer an. Wir melden uns so schnell wie möglich bei Ihnen zurück. Vielen Dank für Ihr Verständnis und einen schönen Tag wünscht Ihnen das Team der Buchhandlung Lesezeit. Nummer 57 Ja. Willkommen zum großen Jubiläumsfest im Schlossgarten. Heute erwartet Sie ein abwechslungsreiches Programm für die ganze Familie. Auf der Hauptbühne treten verschiedene Musikgruppen aus der Region auf. Für das leibliche Wohl sorgen zahlreiche Stände mit regionalen Spezialitäten. Kinder können sich auf eine Hüpfburg und kreative Bastelangebote freuen. Bitte beachten Sie, die Musikvorführungen werden ausschließlich von den eingeladenen Künstlern gestaltet. Eigene Instrumente dürfen nicht mitgebracht und nicht genutzt werden. Das Programm endet um 22 Uhr mit einem großen Feuerwerk. Der Eintritt ist frei und alle Besucher sind herzlich eingeladen, den Tag gemeinsam zu genießen. Nummer 58 Herzlich willkommen zu unserem Sommerfest am Stadtplatz. Ab 15 Uhr gibt es ein buntes Programm mit Straßentheater, Zaubershows und kulinarischen Angeboten. Für musikalische Unterhaltung sorgt die Stadtkapelle, die bis in den Abend hineinspielt. Tänzerinnen und Tänzer aus der Tanzschule präsentieren kurze Choreografien auf der Bühne. Bitte beachten Sie! Dies ist keine Tanzveranstaltung für Besucher. Wer selbst tanzen möchte, kann dies nur bei unserem Tanzabend im September tun. Heute steht das Zuschauen und Genießen im Vordergrund. Der Eintritt ist frei und wir freuen uns auf zahlreiche Gäste aus nah und fern. Nummer 59 Liebe Interessierte Unser neues Kursprogramm für das Herbstsemester ist ab sofort verfügbar. Wir bieten Sprachkurse, Kreativworkshops und Sportangebote für alle Altersgruppen an. Die Anmeldung erfolgt ausschließlich persönlich in unserem Büro in der Hauptstraße 12. Bitte bringen Sie Ihren Personalausweis und gegebenenfalls einen Nachweis für Ermäßigungen mit. Eine Online-Registrierung über das Internet ist leider nicht möglich. Unsere Öffnungszeiten sind montags bis freitags von 9 bis 17 Uhr. Wir freuen uns auf Ihre Teilnahme und hoffen, Sie bald in einem unserer Kurse begrüßen zu dürfen. Vielen Dank für Ihr Internesse. Nummer 60 Zum internationalen Kulturfestival in Esens. An diesem Wochenende verwandelt sich die ganze Stadt in eine große Bühne. Auf dem Marktplatz treten Musiker aus Frankreich, Spanien und Brasilien auf, während in den Parkanlagen Theatergruppen aus Italien und Polen ihre Stücke präsentieren. In der Fußgängerzone zeigen Künstlerinnen und Künstler aus aller Welt ihre Malereien und Skulpturen. Alle Veranstaltungen finden an verschiedenen Plätzen gleichzeitig statt, sodass Sie frei entscheiden können, wo Sie zuschauen möchten. Der Eintritt ist zu allen Programmpunkten frei. Vielen Dank. Kommen Sie vorbei und erleben Sie die kulturelle Vielfalt von Esens hautnah. Ende des dritten Teils$j$, segments = $j$[{"end":10.7,"text":"Hörverstehen Teil 3. Sie hören jetzt fünf kurze Texte. Dazu sollen Sie fünf Aufgaben lösen. Sie hören diese Ansage nur einmal.","start":0},{"end":18.42,"text":"Entscheiden Sie beim Hören, ob die Aussagen 56, 60 richtig oder falsch sind.","start":11.3},{"end":21,"text":"Nummer 56","start":19.8},{"end":34.5,"text":"Guten Tag und herzlich willkommen bei der Buchhandlung Lesezeit.","start":30.4},{"end":41.1,"text":"Leider sind wir im Moment nicht persönlich erreichbar. Unser Laden ist heute wegen einer Inventur geschlossen.","start":35.3},{"end":44.2,"text":"Sie können uns aber gerne eine Nachricht hinterlassen.","start":41.8},{"end":49.5,"text":"Bitte nennen Sie dabei Ihren Namen, Ihre Telefonnummer und den Grund Ihres Anrufs.","start":44.7},{"end":56.9,"text":"Falls Sie eine Bestellung aufgeben oder ein bereits bestelltes Buch abholen möchten, geben Sie bitte auch die Bestellnummer an.","start":50.1},{"end":60.2,"text":"Wir melden uns so schnell wie möglich bei Ihnen zurück.","start":57.5},{"end":66.3,"text":"Vielen Dank für Ihr Verständnis und einen schönen Tag wünscht Ihnen das Team der Buchhandlung Lesezeit.","start":60.5},{"end":69.3,"text":"Nummer 57","start":68},{"end":72.2,"text":"Ja.","start":71.5},{"end":89,"text":"Willkommen zum großen Jubiläumsfest im Schlossgarten. Heute erwartet Sie ein abwechslungsreiches Programm für die ganze Familie.","start":79.9},{"end":99.6,"text":"Auf der Hauptbühne treten verschiedene Musikgruppen aus der Region auf. Für das leibliche Wohl sorgen zahlreiche Stände mit regionalen Spezialitäten.","start":89.5},{"end":105.2,"text":"Kinder können sich auf eine Hüpfburg und kreative Bastelangebote freuen.","start":99.9},{"end":112.7,"text":"Bitte beachten Sie, die Musikvorführungen werden ausschließlich von den eingeladenen Künstlern gestaltet.","start":105.6},{"end":117.3,"text":"Eigene Instrumente dürfen nicht mitgebracht und nicht genutzt werden.","start":113.5},{"end":122.6,"text":"Das Programm endet um 22 Uhr mit einem großen Feuerwerk.","start":117.6},{"end":129.7,"text":"Der Eintritt ist frei und alle Besucher sind herzlich eingeladen, den Tag gemeinsam zu genießen.","start":122.9},{"end":132.9,"text":"Nummer 58","start":131.7},{"end":160.3,"text":"Herzlich willkommen zu unserem Sommerfest am Stadtplatz. Ab 15 Uhr gibt es ein buntes Programm mit Straßentheater, Zaubershows und kulinarischen Angebote